<div class="d-flex justify-content-between mb-3"><h1 class="h3">Staff</h1><a class="btn btn-primary" href="<?= site_url('users/new') ?>">+ Add Staff</a></div><div class="card shadow-sm"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Avatar</th><th>Full Name</th><th>Username</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?php if($u['avatar']): ?><img class="avatar" src="<?= base_url('uploads/avatars/'.$u['avatar']) ?>" alt=""><?php else: ?><span class="avatar-fallback"><?= esc(strtoupper(substr($u['full_name'],0,1))) ?></span><?php endif ?></td><td class="fw-semibold"><?= esc($u['full_name']) ?></td><td><?= esc($u['username']) ?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="<?= site_url('users/'.$u['id'].'/edit') ?>">Edit</a><?= form_open('users/'.$u['id'],['class'=>'d-inline','onsubmit'=>"return confirm('Delete this staff account?')"]) ?><input type="hidden" name="_method" value="DELETE"><button class="btn btn-sm btn-outline-danger">Delete</button><?= form_close() ?></td></tr><?php endforeach ?></tbody></table></div></div>
